const props=defineProps<{block:DecorationBlock;imageUrl:(id:string)=>string;editable?:boolean;member?:DecorationMember|null;primary:string;location?:string}>()
const emit=defineEmits<{navigate:[target:DecorationLink];locate:[]}>()
const o=computed(()=>decorationOptions(props.block)),items=computed(()=>visibleDecorationItems(props.block)),hot=ref(0),slide=ref(0),allTabs=ref(false),activeTab=ref('home')
const searchRoot=shallowRef<HTMLElement|null>(null),searchHeader=shallowRef<HTMLElement|null>(null),searchPortal=shallowRef<HTMLElement|null>(null),stuck=ref(false),headerHeight=ref(0),headerPosition=ref({left:0,top:0,width:0})
let searchScroll:HTMLElement|null=null,searchObserver:ResizeObserver|undefined
function measureSearch(){const root=searchRoot.value,header=searchHeader.value,portal=searchPortal.value;if(!root||!header||!portal)return;headerHeight.value=header.offsetHeight;const rect=root.getBoundingClientRect(),frame=portal.getBoundingClientRect(),content=portal.querySelector('.preview-content')?.getBoundingClientRect(),scale=frame.width/portal.offsetWidth;stuck.value=o.value.searchFixed&&!!content&&rect.top<content.top-.5;headerPosition.value={left:(rect.left-frame.left)/scale,top:portal.querySelector<HTMLElement>('.preview-title')?.offsetHeight||0,width:root.offsetWidth}}
onMounted(()=>{if(props.block.type!=='search')return;searchPortal.value=searchRoot.value?.closest<HTMLElement>('.decoration-preview')||null;searchScroll=searchPortal.value?.querySelector<HTMLElement>('.preview-content')||null;searchScroll?.addEventListener('scroll',measureSearch,{passive:true});searchObserver=new ResizeObserver(measureSearch);if(searchRoot.value)searchObserver.observe(searchRoot.value);nextTick(measureSearch)})
